SELECT symbol, id, signal_mode, generated_at, decision, latest_price FROM crypto_ai.trade_signal WHERE interval_code = '1m' AND ((symbol = 'EGLDUSDT' AND generated_at BETWEEN '2026-10-11 20:25:00' AND '2026-10-11 20:55:02') OR (symbol = 'EGLDUSDT' AND generated_at BETWEEN '2026-10-11 22:10:00' AND '2026-10-11 22:40:02') OR (symbol = 'XRPUSDT' AND generated_at BETWEEN '2026-10-12 02:05:00' AND '2026-10-12 02:35:02') OR (symbol = 'DOGEUSDT' AND generated_at BETWEEN '2026-10-12 03:32:00' AND '2026-10-12 04:02:03') OR (symbol = 'SHIBUSDT' AND generated_at BETWEEN '2026-10-12 06:06:00' AND '2026-10-12 06:36:02') OR (symbol = 'ACEUSDT' AND generated_at BETWEEN '2026-10-12 09:27:00' AND '2026-10-12 09:57:02')) ORDER BY symbol, generated_at LIMIT 400;